/**
 * Guards the bundled sample statute.
 *
 * The built-in JSON is regenerated by the parser from time to time, so this is
 * really a contract check: whatever ships in `public/data/` must satisfy every
 * assumption the reader makes. CI runs against the real shipped bytes, so a
 * bad export is caught here rather than as an empty reader in front of a user.
 */

import { describe, expect, it } from 'vitest';

import sample from '../../public/data/cgst-act.json';
import { BUILTIN_DOCUMENTS, summarizeDataset, validateDataset } from '../services/documentLibrary';
import { buildIndex } from '../services/aknLoader';

/**
 * `buildIndex` releases the raw arrays in place to save heap, so the payload is
 * validated and counted first, then indexed. Sharing one indexed dataset across
 * tests would assert against emptied arrays.
 */
const raw = validateDataset(structuredClone(sample), 'sample');
const payloadCounts = {
  provisions: raw.provisions.length,
  citations: raw.citations.length,
  footnotes: raw.footnotes.length,
};
const summary = summarizeDataset(raw);
const index = buildIndex(raw);

describe('bundled sample statute', () => {
  it('passes validation and reports a known schema', () => {
    expect(sample.schema_version).toBe('akn.statute.v1');
    expect(payloadCounts.provisions).toBeGreaterThan(0);
  });

  it('carries the title the library card renders', () => {
    expect(sample.akomaNtoso?.act?.meta?.title).toBe('The Central Goods and Services Tax Act, 2017');
  });

  it('has no duplicate or missing provision ids', () => {
    expect(index.provisionsByEid.size).toBe(payloadCounts.provisions);
  });

  it('resolves every citation parent and every internal target', () => {
    expect(index.quality.internalResolved).toBeGreaterThan(0);
    expect(index.quality.internalUnresolved).toBe(0);
  });

  it('indexes a navigable hierarchy of chapters, sections and schedules', () => {
    expect(index.readingOrder.length).toBeGreaterThan(0);
    expect(index.sectionsByNum.size).toBeGreaterThan(100);

    // Every provision must be reachable from a root, or it never renders.
    const reached = new Set<string>();
    const walk = (eid: string): void => {
      if (reached.has(eid)) return;
      reached.add(eid);
      for (const child of index.provisionsByEid.get(eid)?.children ?? []) walk(child.eid);
    };
    for (const provision of index.provisions) {
      if (!provision.parent_eid) walk(provision.eid);
    }
    expect(reached.size).toBe(payloadCounts.provisions);
  });

  it('reads as a complete document, not fragments', () => {
    const rootKinds = new Set(index.readingOrder.map((p) => p.kind));
    expect(rootKinds.has('chapter')).toBe(true);
    expect(rootKinds.has('schedule')).toBe(true);
    expect(rootKinds.has('section')).toBe(true);

    // Detached/unattributed provisions are carried in the walk, not dropped.
    expect(index.documentOrder.length).toBeGreaterThanOrEqual(index.readingOrder.length);
  });

  it('summarises to counts consistent with the payload', () => {
    expect(summary.provisions).toBe(payloadCounts.provisions);
    expect(summary.sections).toBe(index.quality.sectionCount);
    expect(summary.citations).toBe(payloadCounts.citations);
    expect(summary.footnotes).toBe(payloadCounts.footnotes);
    expect(summary.containers).toBeGreaterThan(0);
  });

  it('is the document the built-in catalogue points at', () => {
    const builtin = BUILTIN_DOCUMENTS.find((d) => d.origin === 'builtin');
    expect(builtin?.dataUrl).toBe('data/cgst-act.json');
    expect(builtin?.title).toBe(sample.akomaNtoso?.act?.meta?.title);
  });
});